2	import { useMiaActions } from '@/hooks/useMiaActions';
3	import type { MiaActionHandler } from '@/types/mia';
4	
5	export interface ProntaEntregaMiaInterface {
6	  // View mode
7	  setViewMode: (v: 'board' | 'analytics') => void;
8	
9	  // Search
10	  setSearch: (v: string) => void;
11	
12	  // Create dialog
13	  setIsCreateOpen: (v: boolean) => void;
14	  setForm: (updater: (prev: any) => any) => void;
15	
16	  // Detail modal
17	  setItemToDetail: (item: any | null) => void;
18	
19	  // Analytics filter (admin only)
20	  setAnalyticsStoreId: (v: string) => void;
21	
22	  // Data
23	  items: any[];
24	  fetchItems: () => void;
25	
26	  // Move & consume actions
27	  handleMove: (item: any, newLocation: 'congelado' | 'resfriado' | 'expositor') => void;
28	  handleConsume: () => void;
29	  handleDelete?: (id: string, name: string) => void;
30	}
31	
32	export function useMiaProntaEntregaActions(iface: ProntaEntregaMiaInterface): void {
33	  const {
34	    setViewMode,
35	    setSearch,
36	    setIsCreateOpen,
37	    setForm,
38	    setItemToDetail,
39	    setAnalyticsStoreId,
40	    items,
41	    fetchItems,
42	    handleMove,
43	    handleConsume,
44	    handleDelete,
45	  } = iface;
46	
47	  const findItem = (data: Record<string, any> | undefined) => {
48	    if (!data) return null;
49	    if (data.item_id) {
50	      return items.find((i: any) => i.id === data.item_id) || null;
51	    }
52	    if (data.product_name) {
53	      return items.find(
54	        (i: any) => i.product_name?.toLowerCase().includes(data.product_name.toLowerCase())
55	      ) || null;
56	    }
57	    return null;
58	  };
59	
60	  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
61	    // ── Switch view mode ──
62	    pronta_switch_view: {
63	      id: 'pronta_switch_view',
64	      description: 'Trocar visão entre Quadro e Analytics',
65	      execute: (data) => {
66	        if (data?.view === 'board' || data?.view === 'analytics') {
67	          setViewMode(data.view);
68	        }
69	      },
70	    },
71	
72	    // ── Search ──
73	    pronta_search: {
74	      id: 'pronta_search',
75	      description: 'Buscar produto na pronta entrega',
76	      execute: (data) => {
77	        if (data?.search !== undefined) {
78	          setSearch(data.search);
79	        }
80	      },
81	    },
82	
83	    // ── Create item ──
84	    pronta_create: {
85	      id: 'pronta_create',
86	      description: 'Abrir formulário de novo produto e preencher dados',
87	      execute: (data) => {
88	        setIsCreateOpen(true);
89	        if (data) {
90	          setForm((prev: any) => ({
91	            ...prev,
92	            ...(data.product_name !== undefined ? { product_name: data.product_name } : {}),
93	            ...(data.location !== undefined ? { location: data.location } : {}),
94	            ...(data.entry_date !== undefined ? { entry_date: data.entry_date } : {}),
95	            ...(data.validity_date !== undefined ? { validity_date: data.validity_date } : {}),
96	          }));
97	        }
98	      },
99	    },
100	
101	    // ── Open detail modal ──
102	    pronta_open_detail: {
103	      id: 'pronta_open_detail',
104	      description: 'Abrir detalhes de um item da pronta entrega',
105	      execute: (data) => {
106	        const item = findItem(data);
107	        if (item) {
108	          setItemToDetail(item);
109	        }
110	      },
111	    },
112	
113	    // ── Move item ──
114	    pronta_move: {
115	      id: 'pronta_move',
116	      description: 'Mover item entre localizações (congelado, resfriado, expositor)',
117	      execute: (data) => {
118	        if (!data?.location) return;
119	        const item = findItem(data);
120	        if (item) {
121	          handleMove(item, data.location);
122	        }
123	      },
124	    },
125	
126	    // ── Consume / sell item ──
127	    pronta_consume: {
128	      id: 'pronta_consume',
129	      description: 'Registrar saída/venda de um item',
130	      execute: (data) => {
131	        const item = findItem(data);
132	        if (item) {
133	          setItemToDetail(item);
134	          // Small delay so the detail modal renders before consume
135	          setTimeout(() => handleConsume(), 150);
136	        }
137	      },
138	    },
139	
140	    // ── Delete item ──
141	    pronta_delete: {
142	      id: 'pronta_delete',
143	      description: 'Excluir permanentemente um item da pronta entrega',
144	      execute: async (data) => {
145	        const item = findItem(data);
146	        if (item) {
147	          handleDelete?.(item.id, item.product_name);
148	        }
149	      },
150	    },
151	
152	    // ── Analytics store filter (admin) ──
153	    pronta_analytics_filter: {
154	      id: 'pronta_analytics_filter',
155	      description: 'Filtrar analytics por loja (admin)',
156	      execute: (data) => {
157	        if (data?.store_id !== undefined) {
158	          setAnalyticsStoreId(String(data.store_id));
159	        }
160	      },
161	    },
162	
163	    // ── Refresh data ──
164	    pronta_refresh: {
165	      id: 'pronta_refresh',
166	      description: 'Atualizar dados da pronta entrega',
167	      execute: () => {
168	        fetchItems();
169	      },
170	    },
171	
172	    // ── Clear filters ──
173	    clear_filters: {
174	      id: 'clear_filters',
175	      description: 'Limpar busca da pronta entrega',
176	      execute: () => {
177	        setSearch('');
178	      },
179	    },
180	  }), [
181	    setViewMode,
182	    setSearch,
183	    setIsCreateOpen,
184	    setForm,
185	    setItemToDetail,
186	    setAnalyticsStoreId,
187	    items,
188	    fetchItems,
189	    handleMove,
190	    handleConsume,
191	    handleDelete,
192	  ]);
193	
194	  useMiaActions('/pronta-entrega', handlers);
195	}
