8	// (via useMiaGlassBoxContextInjector) recebe esses hints e usa no prompt.
9	//
10	// Uso típico:
11	//   useMiaPageContext({
12	//     description: 'Gestão de contas a pagar do financeiro',
13	//     natural_language_hints: '"vencidas" = status=vencida; "fechamento" = exportar PDF semana',
14	//     capabilities: ['consultar', 'pagar', 'agendar', 'cancelar'],
15	//     destructive_actions: ['cancelar', 'pagar-lote'],
16	//   })
17	//
18	// Doc: docs/mia/ARCHITECTURE.md (Section 8.5), docs/mia/DATA_MIA_CONVENTION.md
19	
20	import { useEffect, useRef } from 'react';
21	import { useLocation } from 'react-router-dom';
22	import { supabase } from '@/integrations/supabase/client';
23	
24	export interface MiaPageContextHint {
25	  /** Descrição em linguagem natural da página (1-2 frases). */
26	  description?: string;
27	  /** Hints de linguagem natural — mapas "frase do user → ação/filtro". */
28	  natural_language_hints?: string;
29	  /** Capacidades operacionais expostas (ex: ['consultar', 'pagar']). */
30	  capabilities?: string[];
31	  /** Ações que precisam de confirmação extra. */
32	  destructive_actions?: string[];
33	  /** Entidade primária (ex: 'conta_pagar'). */
34	  primary_entity?: string;
35	  /** Outras metadados específicas do domínio. */
36	  extra?: Record<string, unknown>;
37	}
38	
39	/**
40	 * Hook pra páginas declararem contexto extra MIA-friendly.
41	 *
42	 * Roda 1× após mount (e após mudanças no hint via deps). Faz upsert em
43	 * mia_page_models.manual_context. Backend lê via injector → screen_state.
44	 */
45	export function useMiaPageContext(hint: MiaPageContextHint, deps: unknown[] = []) {
46	  const location = useLocation();
47	  const lastSerializedRef = useRef<string>('');
48	
49	  useEffect(() => {
50	    const path = location.pathname;
51	    if (!path || !hint) return;
52	
53	    const payload = {
54	      description: hint.description,
55	      natural_language_hints: hint.natural_language_hints,
56	      capabilities: hint.capabilities,
57	      destructive_actions: hint.destructive_actions,
58	      primary_entity: hint.primary_entity,
59	      ...(hint.extra ?? {}),
60	    };
61	
62	    const serialized = JSON.stringify({ path, payload });
63	    if (serialized === lastSerializedRef.current) return;
64	    lastSerializedRef.current = serialized;
65	
66	    void (async () => {
67	      try {
68	        // Upsert: cria row se não existe, ou atualiza manual_context da existente.
69	        // Page Model "esqueleto" (sem domain/actions) — discovery posterior popula.
70	        const { data: existing } = await supabase
71	          .from('mia_page_models')
72	          .select('page_path, domain, description, natural_language_hints, manual_context')
73	          .eq('page_path', path)
74	          .maybeSingle();
75	
76	        if (existing) {
77	          // Update ONLY campos manuais — preserva domain auto-descoberto
78	          // se existir. Não altera confidence (responsabilidade do auto-discover).
79	          await supabase
80	            .from('mia_page_models')
