89	          // Discovery posterior (useMiaAutoDiscover) preencherá actions/entities
90	          // E aumenta confidence quando detectar elementos data-mia-*.
91	          // Confidence inicial baixa (0.4) pra ficar abaixo do threshold de
92	          // persistência do auto-discover (que só promove se ≥ 0.40 com
93	          // elementos reais) — assim auto-discover sempre vai dominar.
94	          await supabase.from('mia_page_models').insert({
95	            page_path: path,
96	            domain: 'unknown',
97	            description: hint.description,
98	            natural_language_hints: hint.natural_language_hints,
99	            manual_context: payload,
100	            confidence: 0.4,
101	          });
102	        }
103	      } catch (err) {
104	        // Não-crítico — falha silenciosa
105	        console.debug('[MIA useMiaPageContext] upsert failed:', err);
106	      }
107	    })();
108	    // eslint-disable-next-line react-hooks/exhaustive-deps
109	  }, [location.pathname, ...deps]);
110	}
