5	/**
6	 * Hook for pages to register their available MIA actions.
7	 * Actions are automatically unregistered when the component unmounts.
8	 *
9	 * Usage:
10	 * ```
11	 * useMiaActions('/financeiro', {
12	 *   select_tab: {
13	 *     id: 'select_tab',
14	 *     description: 'Selecionar aba do módulo financeiro',
15	 *     execute: (data) => setActiveModule(data?.tab),
16	 *   },
17	 *   open_modal: {
18	 *     id: 'open_modal',
19	 *     description: 'Abrir modal de nova conta',
20	 *     execute: (data) => setShowNewAccountModal(true),
21	 *   },
22	 * });
23	 * ```
24	 */
25	export function useMiaActions(
26	  route: string,
27	  handlers: Record<string, MiaActionHandler>
28	) {
29	  const { registerActions, unregisterActions } = useMia();
30	
31	  useEffect(() => {
32	    registerActions(route, handlers);
33	    return () => unregisterActions(route);
34	  }, [route, registerActions, unregisterActions]);
35	  // Note: handlers is intentionally not in deps to avoid re-registration on every render
36	  // Pages should memoize their handlers or define them outside the component
37	}
