1	/**
2	 * @module features/gestao/model/useGestaoKpis
3	 *
4	 * KPIs derivados do bus `eventos_operacionais` (fluxo: count do dia por tipo)
5	 * e das tabelas de domínio (estado: rupturas, mínimos, produção).
6	 *
7	 * Cada setor expõe suas próprias queries; este hook agrega o fluxo genérico
8	 * (counts por tipo_evento de hoje) que todos os setores usam como base.
9	 */
10	
11	import { useEffect } from 'react';
12	import { useQuery, useQueryClient } from '@tanstack/react-query';
13	import { supabase } from '@/integrations/supabase/client';
14	import type { Setor } from './types';
15	
16	export const kpisKeys = {
17	  fluxo: (setor: Setor) => ['gestao', 'kpis', 'fluxo', setor] as const,
18	  estoque: () => ['gestao', 'kpis', 'estoque'] as const,
19	  producao: () => ['gestao', 'kpis', 'producao'] as const,
20	  logistica: () => ['gestao', 'kpis', 'logistica'] as const,
21	};
22	
23	/** Contagem de eventos de hoje por tipo_evento para um setor. */
24	async function fetchFluxoKpis(
25	  setor: Setor,
26	): Promise<Record<string, number>> {
27	  const hoje = new Date();
28	  hoje.setHours(0, 0, 0, 0);
29	
30	  const { data, error } = await supabase
31	    .from('eventos_operacionais')
32	    .select('tipo_evento')
33	    .eq('setor', setor)
34	    .gte('criado_em', hoje.toISOString());
35	
36	  if (error) throw error;
37	
38	  const counts: Record<string, number> = {};
39	  for (const row of data ?? []) {
40	    counts[row.tipo_evento] = (counts[row.tipo_evento] ?? 0) + 1;
41	  }
42	  return counts;
43	}
44	
45	/** Hook de KPIs de fluxo do dia para um setor. */
46	export function useFluxoKpis(setor: Setor): {
47	  counts: Record<string, number>;
48	  isLoading: boolean;
49	} {
50	  const queryClient = useQueryClient();
51	
52	  const { data, isLoading } = useQuery({
53	    queryKey: kpisKeys.fluxo(setor),
54	    queryFn: () => fetchFluxoKpis(setor),
55	    staleTime: 60_000, // KPIs de fluxo: 1 min de cache
56	    refetchInterval: 5 * 60_000, // revalidar a cada 5 min
57	  });
58	
59	  useEffect(() => {
60	    const handler = () => {
61	      queryClient.invalidateQueries({ queryKey: kpisKeys.fluxo(setor) });
62	    };
63	
64	    const channel = supabase
65	      .channel(`gestao-kpis-${setor}`)
66	      .on(
67	        'postgres_changes',
68	        {
69	          event: 'INSERT',
70	          schema: 'public',
71	          table: 'eventos_operacionais',
72	          filter: `setor=eq.${setor}`,
73	        },
74	        handler,
75	      )
76	      .subscribe();
77	
78	    return () => {
79	      supabase.removeChannel(channel);
80	    };
81	  }, [setor, queryClient]);
82	
83	  return { counts: data ?? {}, isLoading };
84	}
85	
86	// ─── KPIs de Estado: Estoque ───────────────────────────────────────────────
87	
88	export interface EstoqueEstadoKpis {
89	  rupturas: number;
90	  abaixoMinimo: number;
91	  isLoading: boolean;
92	}
93	
94	/** Rupturas e abaixo-do-mínimo da loja do usuário (RLS já escopa). */
95	export function useEstoqueEstadoKpis(): EstoqueEstadoKpis {
96	  const { data, isLoading } = useQuery({
97	    queryKey: kpisKeys.estoque(),
98	    queryFn: async () => {
99	      // Rupturas: quantidade_atual <= 0, não oculto
100	      const { count: rupturas, error: e1 } = await supabase
101	        .from('estoque')
102	        .select('id', { count: 'exact', head: true })
103	        .lte('quantidade_atual', 0)
104	        .not('oculto', 'eq', true);
105	
106	      // Abaixo do mínimo: quantidade_atual < quantidade_minima AND quantidade_minima > 0
107	      const { count: abaixoMinimo, error: e2 } = await supabase
108	        .from('estoque')
109	        .select('id', { count: 'exact', head: true })
110	        .gt('quantidade_minima', 0)
111	        // RPC ou filter expression — usar filter com rpc não disponível; aproximar:
112	        // Supabase .lt com coluna só funciona com constante. Usamos .filter()
113	        .filter('quantidade_atual', 'lt', 'quantidade_minima');
114	
115	      if (e1 || e2) throw e1 ?? e2;
116	
117	      return {
118	        rupturas: rupturas ?? 0,
119	        abaixoMinimo: abaixoMinimo ?? 0,
120	      };
121	    },
122	    staleTime: 60_000,
123	  });
124	
125	  return {
126	    rupturas: data?.rupturas ?? 0,
127	    abaixoMinimo: data?.abaixoMinimo ?? 0,
128	    isLoading,
129	  };
130	}
131	
132	// ─── KPIs de Estado: Produção ──────────────────────────────────────────────
133	
134	export interface ProducaoRag {
135	  /** null = não lançada ainda; string ISO = hora do lançamento */
136	  lancadaEm: string | null;
137	  /** 'verde' | 'ambar' | 'vermelho' */
138	  rag: 'verde' | 'ambar' | 'vermelho';
139	  totalUnidades: number;
140	  itens: number;
141	}
142	
143	/**
144	 * Classifica o status do lançamento de produção de hoje.
145	 * Verde = lançada; Âmbar = não lançada antes 12:00 (hora local);
146	 * Vermelho = não lançada depois 12:00.
147	 */
148	export function classifyProducaoRag(
149	  lancadaEm: string | null,
150	  agora: Date = new Date(),
151	): 'verde' | 'ambar' | 'vermelho' {
152	  if (lancadaEm !== null) return 'verde';
153	  const hora = agora.getHours() + agora.getMinutes() / 60;
154	  return hora < 12 ? 'ambar' : 'vermelho';
155	}
156	
157	export function useProducaoEstadoKpis(): ProducaoRag & { isLoading: boolean } {
158	  const { data, isLoading } = useQuery({
159	    queryKey: kpisKeys.producao(),
160	    queryFn: async () => {
161	      // Busca o último evento producao.lancada de hoje
162	      const hoje = new Date();
163	      hoje.setHours(0, 0, 0, 0);
164	
165	      const { data: eventos, error } = await supabase
166	        .from('eventos_operacionais')
167	        .select('payload, criado_em')
168	        .eq('setor', 'producao')
169	        .eq('tipo_evento', 'producao.lancada')
170	        .gte('criado_em', hoje.toISOString())
171	        .order('criado_em', { ascending: false })
172	        .limit(1);
173	
174	      if (error) throw error;
175	
176	      if (!eventos || eventos.length === 0) {
177	        return { lancadaEm: null, totalUnidades: 0, itens: 0 };
178	      }
179	
180	      const ev = eventos[0];
181	      const p = ev.payload as Record<string, unknown>;
182	      return {
183	        lancadaEm: ev.criado_em,
184	        totalUnidades: typeof p?.total_unidades === 'number' ? p.total_unidades : 0,
185	        itens: Array.isArray(p?.itens) ? (p.itens as unknown[]).length : typeof p?.itens === 'number' ? p.itens : 0,
186	      };
187	    },
188	    staleTime: 60_000,
189	    refetchInterval: 5 * 60_000,
190	  });
191	
192	  const lancadaEm = data?.lancadaEm ?? null;
193	  const rag = classifyProducaoRag(lancadaEm);
194	
195	  return {
196	    lancadaEm,
197	    rag,
198	    totalUnidades: data?.totalUnidades ?? 0,
199	    itens: data?.itens ?? 0,
200	    isLoading,
201	  };
202	}
203	
204	// ─── KPIs de Estado: Logística ─────────────────────────────────────────────
205	
206	export interface LogisticaEstadoKpis {
207	  /** Contagem de requisições por status hoje. */
208	  porStatus: Record<string, number>;
209	  isLoading: boolean;
210	}
211	
212	export function useLogisticaEstadoKpis(): LogisticaEstadoKpis {
213	  const { data, isLoading } = useQuery({
214	    queryKey: kpisKeys.logistica(),
215	    queryFn: async () => {
216	      const hoje = new Date();
217	      hoje.setHours(0, 0, 0, 0);
218	
219	      const { data: rows, error } = await supabase
220	        .from('requisicoes')
221	        .select('status')
222	        .gte('created_at', hoje.toISOString());
223	
224	      if (error) throw error;
225	
226	      const counts: Record<string, number> = {};
227	      for (const r of rows ?? []) {
228	        const s = (r as { status: string }).status ?? 'desconhecido';
229	        counts[s] = (counts[s] ?? 0) + 1;
230	      }
231	      return counts;
232	    },
233	    staleTime: 60_000,
234	    refetchInterval: 5 * 60_000,
235	  });
236	
237	  return { porStatus: data ?? {}, isLoading };
238	}
