/**
 * @module features/pronta-entrega/model/saldos
 *
 * Funções puras do domínio Pronta Entrega: merge dos saldos de câmara fria
 * (`estoque`) com os saldos de vitrine (`expositora_estoque`) e filtro de
 * busca por nome. Sem dependências de React/Supabase — testável isolado.
 */

/** Fábrica (loja_id=1) não tem expositora — a página é exclusiva das lojas. */
export const FABRICA_LOJA_ID = 1;

/** Linha crua de uma das fontes (estoque ou expositora) já com join de produto. */
export interface SaldoSourceRow {
  produtoId: number;
  nome: string;
  setor: string | null;
  quantidade: number;
}

/** Saldo unificado de um produto na loja: câmara fria + expositora. */
export interface SaldoRow {
  produtoId: number;
  nome: string;
  setor: string | null;
  /** Quantidade na câmara fria/congelado (`estoque.quantidade_atual`). */
  estoque: number;
  /** Quantidade exposta no salão (`expositora_estoque.quantidade`). Pode ser negativa (furo de processo). */
  expositora: number;
  /** estoque + expositora. */
  total: number;
}

/**
 * Faz o merge por `produtoId` das linhas de estoque (câmara) com as da
 * expositora. Mantém apenas produtos com estoque \> 0 OU expositora ≠ 0,
 * e ordena por nome (pt-BR).
 *
 * @param estoqueRows - Linhas da câmara fria (quantidade_atual).
 * @param expositoraRows - Linhas da expositora (quantidade; pode ser negativa).
 * @returns Saldos unificados, filtrados e ordenados por nome.
 */
export function mergeSaldos(
  estoqueRows: SaldoSourceRow[],
  expositoraRows: SaldoSourceRow[],
): SaldoRow[] {
  const byProduto = new Map<number, SaldoRow>();

  for (const row of estoqueRows) {
    const existing = byProduto.get(row.produtoId);
    if (existing) {
      existing.estoque += row.quantidade;
    } else {
      byProduto.set(row.produtoId, {
        produtoId: row.produtoId,
        nome: row.nome,
        setor: row.setor,
        estoque: row.quantidade,
        expositora: 0,
        total: 0,
      });
    }
  }

  for (const row of expositoraRows) {
    const existing = byProduto.get(row.produtoId);
    if (existing) {
      existing.expositora += row.quantidade;
      if (!existing.nome && row.nome) existing.nome = row.nome;
      if (existing.setor === null && row.setor !== null) existing.setor = row.setor;
    } else {
      byProduto.set(row.produtoId, {
        produtoId: row.produtoId,
        nome: row.nome,
        setor: row.setor,
        estoque: 0,
        expositora: row.quantidade,
        total: 0,
      });
    }
  }

  return [...byProduto.values()]
    .filter((r) => r.estoque > 0 || r.expositora !== 0)
    .map((r) => ({ ...r, total: r.estoque + r.expositora }))
    .sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
}

/** Normaliza texto pra busca: minúsculas e sem acentos. */
export function normalizeSearchText(value: string): string {
  return value
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '');
}

/**
 * Filtra os saldos pelo nome do produto (case/acento-insensível).
 *
 * @param rows - Saldos unificados.
 * @param search - Termo de busca digitado pelo usuário.
 * @returns Linhas cujo nome contém o termo; todas se o termo for vazio.
 */
export function filterSaldos(rows: SaldoRow[], search: string): SaldoRow[] {
  const term = normalizeSearchText(search.trim());
  if (!term) return rows;
  return rows.filter((r) => normalizeSearchText(r.nome).includes(term));
}

/**
 * @module features/pronta-entrega/model/useProntaEntregaSaldos
 *
 * Query unificada dos saldos da loja: câmara fria (`estoque`) + vitrine
 * (`expositora_estoque`), com join em `produtos_master` (apenas ativos).
 * O merge por produto é feito pela função pura {@link mergeSaldos}.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import {
  FABRICA_LOJA_ID,
  mergeSaldos,
  type SaldoRow,
  type SaldoSourceRow,
} from './saldos';

export { mergeSaldos, filterSaldos, FABRICA_LOJA_ID } from './saldos';
export type { SaldoRow, SaldoSourceRow } from './saldos';

export const prontaEntregaKeys = {
  saldos: (lojaId: number | null) => ['pronta-entrega', 'saldos', lojaId] as const,
  historico: (lojaId: number | null) => ['pronta-entrega', 'historico', lojaId] as const,
};

interface ProdutoJoin {
  nome: string;
  setor: string | null;
}

async function fetchSaldos(lojaId: number): Promise<SaldoRow[]> {
  const [estoqueRes, expositoraRes] = await Promise.all([
    supabase
      .from('estoque')
      .select('produto_master_id, quantidade_atual, produtos_master!inner(nome, setor, ativo)')
      .eq('loja_id', lojaId)
      .eq('produtos_master.ativo', true)
      .not('produto_master_id', 'is', null)
      .gt('quantidade_atual', 0),
    supabase
      .from('expositora_estoque')
      .select('produto_master_id, quantidade, produtos_master!inner(nome, setor, ativo)')
      .eq('loja_id', lojaId)
      .eq('produtos_master.ativo', true),
  ]);

  if (estoqueRes.error) throw estoqueRes.error;
  if (expositoraRes.error) throw expositoraRes.error;

  const estoqueRows: SaldoSourceRow[] = (estoqueRes.data ?? []).map((row) => {
    const produto = row.produtos_master as ProdutoJoin;
    return {
      produtoId: row.produto_master_id as number,
      nome: produto?.nome ?? `Produto #${row.produto_master_id}`,
      setor: produto?.setor ?? null,
      quantidade: row.quantidade_atual ?? 0,
    };
  });

  const expositoraRows: SaldoSourceRow[] = (expositoraRes.data ?? []).map((row) => {
    const produto = row.produtos_master as ProdutoJoin;
    return {
      produtoId: row.produto_master_id,
      nome: produto?.nome ?? `Produto #${row.produto_master_id}`,
      setor: produto?.setor ?? null,
      quantidade: row.quantidade ?? 0,
    };
  });

  return mergeSaldos(estoqueRows, expositoraRows);
}

/**
 * Hook de saldos unificados da Pronta Entrega para uma loja.
 * Desabilitado quando não há loja selecionada ou quando a loja é a Fábrica
 * (que não tem expositora).
 *
 * @param lojaId - Loja selecionada (null enquanto o contexto carrega).
 */
export function useProntaEntregaSaldos(lojaId: number | null) {
  const enabled = lojaId !== null && lojaId !== FABRICA_LOJA_ID;

  const query = useQuery({
    queryKey: prontaEntregaKeys.saldos(lojaId),
    queryFn: () => fetchSaldos(lojaId as number),
    enabled,
    staleTime: 30_000,
  });

  return {
    rows: query.data ?? [],
    isLoading: enabled && query.isLoading,
    isError: query.isError,
    refetch: query.refetch,
  };
}

/**
 * @module features/pronta-entrega/model/motivos
 *
 * Motivos válidos do RPC `ajustar_expositora` e labels pt-BR para
 * motivos/tipos do ledger `expositora_movimentacoes`.
 */

/** Motivos aceitos pelo RPC `ajustar_expositora`. */
export type AjusteMotivo =
  | 'perda'
  | 'vencido'
  | 'degustacao'
  | 'consumo_interno'
  | 'recontagem'
  | 'contagem_inicial'
  | 'outro';

/** Opções exibidas no select de motivo do ajuste manual. */
export const AJUSTE_MOTIVO_OPTIONS: { value: AjusteMotivo; label: string }[] = [
  { value: 'perda', label: 'Perda' },
  { value: 'vencido', label: 'Vencido' },
  { value: 'degustacao', label: 'Degustação' },
  { value: 'consumo_interno', label: 'Consumo interno' },
  { value: 'recontagem', label: 'Recontagem' },
  { value: 'outro', label: 'Outro' },
];

const MOTIVO_LABELS: Record<string, string> = {
  perda: 'Perda',
  vencido: 'Vencido',
  degustacao: 'Degustação',
  consumo_interno: 'Consumo interno',
  recontagem: 'Recontagem',
  contagem_inicial: 'Contagem inicial',
  outro: 'Outro',
};

/** Label pt-BR de um motivo do ledger (fallback: humaniza o snake_case). */
export function motivoLabel(motivo: string): string {
  return MOTIVO_LABELS[motivo] ?? motivo.replace(/_/g, ' ');
}

/** Estilo do badge por tipo de movimentação do ledger. */
export const TIPO_BADGE: Record<string, { label: string; className: string }> = {
  entrada: {
    label: 'Entrada',
    className: 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/20',
  },
  saida: {
    label: 'Saída',
    className: 'text-red-600 bg-red-50 dark:bg-red-900/20',
  },
  ajuste: {
    label: 'Ajuste',
    className: 'text-amber-600 bg-amber-50 dark:bg-amber-900/20',
  },
  venda: {
    label: 'Venda',
    className: 'text-[#57715B] bg-[#57715B]/8 dark:bg-[#57715B]/20',
  },
};

/** Badge de um tipo do ledger (fallback neutro pra tipos novos). */
export function tipoBadge(tipo: string): { label: string; className: string } {
  return (
    TIPO_BADGE[tipo] ?? {
      label: tipo.replace(/_/g, ' '),
      className: 'text-muted-foreground bg-muted',
    }
  );
}

/**
 * @module features/pronta-entrega/model/useExpositoraMutations
 *
 * Mutations da expositora via RPCs atômicos do banco:
 * - `mover_para_expositora` — dá baixa na câmara (estoque) e credita a vitrine;
 * - `ajustar_expositora` — ajusta só a vitrine (delta ou recontagem absoluta).
 *
 * Respostas `{ok:false, erro}` viram erro (toast destrutivo); `alertas[]` do
 * retorno são exibidos como toasts de aviso. Toasts de sucesso ficam a cargo
 * de quem chama (pra fluxos em lote não spammarem).
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import { prontaEntregaKeys } from './useProntaEntregaSaldos';
import type { AjusteMotivo } from './motivos';

export interface MoverParaExpositoraInput {
  produtoId: number;
  quantidade: number;
  observacoes?: string;
}

export interface MoverParaExpositoraResult {
  ok: boolean;
  erro?: string;
  estoque_anterior?: number;
  estoque_novo?: number;
  expositora_saldo?: number;
  alertas?: string[];
}

export interface AjustarExpositoraInput {
  produtoId: number;
  quantidade: number;
  modo: 'delta' | 'absoluto';
  motivo: AjusteMotivo;
  observacoes?: string;
}

export interface AjustarExpositoraResult {
  ok: boolean;
  erro?: string;
  saldo_anterior?: number;
  saldo?: number;
  delta?: number;
}

/**
 * Mutations da expositora pra loja selecionada. Invalida saldos + histórico
 * em caso de sucesso.
 *
 * @param lojaId - Loja alvo das operações (null desabilita na prática:
 * mutations rejeitam com erro amigável).
 */
export function useExpositoraMutations(lojaId: number | null) {
  const queryClient = useQueryClient();

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: prontaEntregaKeys.saldos(lojaId) });
    queryClient.invalidateQueries({ queryKey: prontaEntregaKeys.historico(lojaId) });
  };

  const mover = useMutation({
    mutationFn: async (input: MoverParaExpositoraInput): Promise<MoverParaExpositoraResult> => {
      if (lojaId === null) throw new Error('Nenhuma loja selecionada.');
      const { data, error } = await supabase.rpc('mover_para_expositora', {
        p_produto_master_id: input.produtoId,
        p_loja_id: lojaId,
        p_quantidade: input.quantidade,
        p_observacoes: input.observacoes,
      });
      if (error) throw new Error(error.message);
      const result = data as unknown as MoverParaExpositoraResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Erro ao mover produto para a expositora.');
      }
      return result;
    },
    onSuccess: (result) => {
      invalidate();
      for (const alerta of result.alertas ?? []) {
        toast.warning(alerta);
      }
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });

  const ajustar = useMutation({
    mutationFn: async (input: AjustarExpositoraInput): Promise<AjustarExpositoraResult> => {
      if (lojaId === null) throw new Error('Nenhuma loja selecionada.');
      const { data, error } = await supabase.rpc('ajustar_expositora', {
        p_produto_master_id: input.produtoId,
        p_loja_id: lojaId,
        p_quantidade: input.quantidade,
        p_modo: input.modo,
        p_motivo: input.motivo,
        p_observacoes: input.observacoes,
      });
      if (error) throw new Error(error.message);
      const result = data as unknown as AjustarExpositoraResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Erro ao ajustar a expositora.');
      }
      return result;
    },
    onSuccess: () => {
      invalidate();
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });

  return { mover, ajustar };
}

/**
 * @module features/pronta-entrega/model/useExpositoraHistorico
 *
 * Query do ledger `expositora_movimentacoes` da loja (últimos 200, desc),
 * com nome do produto resolvido via join em `produtos_master`.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { FABRICA_LOJA_ID } from './saldos';
import { prontaEntregaKeys } from './useProntaEntregaSaldos';

export interface ExpositoraLedgerRow {
  id: number;
  tipo: string;
  quantidade: number;
  saldoAnterior: number;
  saldoNovo: number;
  motivo: string;
  observacoes: string | null;
  usuarioNome: string | null;
  createdAt: string;
  produtoNome: string;
}

async function fetchHistorico(lojaId: number): Promise<ExpositoraLedgerRow[]> {
  const { data, error } = await supabase
    .from('expositora_movimentacoes')
    .select(
      'id, tipo, quantidade, saldo_anterior, saldo_novo, motivo, observacoes, usuario_nome, created_at, produto_master_id, produtos_master(nome)',
    )
    .eq('loja_id', lojaId)
    .order('created_at', { ascending: false })
    .limit(200);

  if (error) throw error;

  return (data ?? []).map((row) => ({
    id: row.id,
    tipo: row.tipo,
    quantidade: row.quantidade,
    saldoAnterior: row.saldo_anterior,
    saldoNovo: row.saldo_novo,
    motivo: row.motivo,
    observacoes: row.observacoes,
    usuarioNome: row.usuario_nome,
    createdAt: row.created_at,
    produtoNome:
      (row.produtos_master as { nome: string } | null)?.nome ??
      `Produto #${row.produto_master_id}`,
  }));
}

/**
 * Hook do histórico da expositora. Só busca quando `enabled` (ex.: sheet
 * aberto) e quando há loja válida (não-Fábrica).
 *
 * @param lojaId - Loja do ledger.
 * @param enabled - Liga/desliga a query (ex.: visibilidade do sheet).
 */
export function useExpositoraHistorico(lojaId: number | null, enabled: boolean) {
  const queryEnabled = enabled && lojaId !== null && lojaId !== FABRICA_LOJA_ID;

  const query = useQuery({
    queryKey: prontaEntregaKeys.historico(lojaId),
    queryFn: () => fetchHistorico(lojaId as number),
    enabled: queryEnabled,
    staleTime: 15_000,
  });

  return {
    entries: query.data ?? [],
    isLoading: queryEnabled && query.isLoading,
    isError: query.isError,
    refetch: query.refetch,
  };
}

