interface MoverParaExpositoraModalProps {
  produto: SaldoRow | null;
  onOpenChange: (open: boolean) => void;
  onConfirm: (quantidade: number, observacoes?: string) => void;
  isPending: boolean;
}

/**
 * Modal de movimentação câmara → expositora para um produto pré-selecionado.
 */
export function MoverParaExpositoraModal({
  produto,
  onOpenChange,
  onConfirm,
  isPending,
}: MoverParaExpositoraModalProps) {
  const [quantidadeStr, setQuantidadeStr] = useState('1');
  const [observacoes, setObservacoes] = useState('');

  useEffect(() => {
    if (produto) {
      setQuantidadeStr('1');
      setObservacoes('');
    }
  }, [produto?.produtoId]); // eslint-disable-line react-hooks/exhaustive-deps

  const quantidade = useMemo(() => {
    const n = Number(quantidadeStr);
    return Number.isInteger(n) ? n : NaN;
  }, [quantidadeStr]);

  const estoque = produto?.estoque ?? 0;
  const invalida = !Number.isInteger(quantidade) || quantidade < 1;
  const acimaDoEstoque = !invalida && quantidade > estoque;

  const presets = [1, 5, 10];

  return (
    <Dialog open={!!produto} onOpenChange={onOpenChange}>
      <DialogContent
        data-mia-modal="expor-na-vitrine"
        className="sm:max-w-[425px] bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl border-white/20 dark:border-white/10 rounded-3xl shadow-2xl"
      >
        <DialogHeader>
