                <span className={cn('font-bold', produto.expositora < 0 && 'text-red-600')}>
                  {produto.expositora}
                </span>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="mover-quantidade">Quantidade</Label>
              <div className="flex gap-2">
                {presets.map((preset) => (
                  <Button
                    key={preset}
                    type="button"
                    variant="outline"
                    size="sm"
                    disabled={preset > estoque}
                    data-mia-action={`preset-${preset}`}
                    onClick={() => setQuantidadeStr(String(preset))}
                    className={cn(
                      'h-9 flex-1 rounded-xl border-[#57715B]/20 font-bold',
                      quantidade === preset
                        ? 'bg-[#57715B] text-white hover:bg-[#465b49] hover:text-white'
                        : 'text-[#57715B] hover:bg-[#57715B]/10',
                    )}
                  >
                    {preset}
                  </Button>
                ))}
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={estoque <= 0}
                  data-mia-action="preset-tudo"
                  onClick={() => setQuantidadeStr(String(estoque))}
                  className={cn(
                    'h-9 flex-1 rounded-xl border-[#57715B]/20 font-bold',
                    quantidade === estoque && estoque > 0
                      ? 'bg-[#57715B] text-white hover:bg-[#465b49] hover:text-white'
                      : 'text-[#57715B] hover:bg-[#57715B]/10',
                  )}
                >
                  Tudo
                </Button>
              </div>
              <Input
                id="mover-quantidade"
                data-mia-field="quantidade"
                type="number"
                inputMode="numeric"
                min={1}
                step={1}
                value={quantidadeStr}
                onChange={(e) => setQuantidadeStr(e.target.value)}
                className="h-11 rounded-xl text-lg font-bold tabular-nums"
              />
              {acimaDoEstoque && (
                <div className="flex items-start gap-2 rounded-xl bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-900/40 p-3 text-xs text-amber-700 dark:text-amber-400">
                  <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
                  <span>
                    Quantidade acima do saldo da câmara ({estoque}). Confirme se é isso mesmo — o
                    estoque vai ficar negativo.
                  </span>
                </div>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="mover-observacoes">Observações (opcional)</Label>
              <Textarea
                id="mover-observacoes"
                data-mia-field="observacoes"
                value={observacoes}
                onChange={(e) => setObservacoes(e.target.value)}
                placeholder="Ex.: reposição da vitrine da tarde"
                className="rounded-xl resize-none"
                rows={2}
              />
            </div>
          </div>
        )}

        <DialogFooter className="gap-2 sm:gap-0">
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            disabled={isPending}
            className="rounded-xl h-11"
          >
            Cancelar
          </Button>
          <Button
            data-mia-action="confirmar-expor"
            onClick={() => onConfirm(quantidade, observacoes.trim() || undefined)}
            disabled={invalida || isPending}
            className="rounded-xl h-11 bg-[#57715B] hover:bg-[#465b49] text-white font-bold"
          >
            <ArrowRightToLine className="w-4 h-4 mr-2" />
            {isPending ? 'Movendo...' : 'Mover pra expositora'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

