/**
 * Modal de ajuste (delta ou recontagem absoluta) da expositora de um produto.
 */
export function AjusteExpositoraModal({
  produto,
  onOpenChange,
  onConfirm,
  isPending,
}: AjusteExpositoraModalProps) {
  const [modo, setModo] = useState<'delta' | 'absoluto'>('delta');
  const [quantidadeStr, setQuantidadeStr] = useState('');
  const [motivo, setMotivo] = useState<AjusteMotivo | ''>('');
  const [observacoes, setObservacoes] = useState('');

  useEffect(() => {
    if (produto) {
      setModo('delta');
      setQuantidadeStr('');
      setMotivo('');
      setObservacoes('');
    }
  }, [produto?.produtoId]); // eslint-disable-line react-hooks/exhaustive-deps

  const quantidade = useMemo(() => {
    if (quantidadeStr.trim() === '' || quantidadeStr === '-') return NaN;
    const n = Number(quantidadeStr);
    return Number.isInteger(n) ? n : NaN;
  }, [quantidadeStr]);

  const saldoAtual = produto?.expositora ?? 0;
  const quantidadeInvalida =
    !Number.isInteger(quantidade) ||
    (modo === 'delta' && quantidade === 0) ||
    (modo === 'absoluto' && quantidade < 0);
  const saldoNovo = modo === 'delta' ? saldoAtual + (quantidade || 0) : quantidade;

  const handleModoChange = (value: string) => {
    const next = value === 'absoluto' ? 'absoluto' : 'delta';
    setModo(next);
    setQuantidadeStr('');
    if (next === 'absoluto' && !motivo) setMotivo('recontagem');
  };

  const stepDelta = (step: number) => {
    const atual = Number.isInteger(quantidade) ? quantidade : 0;
    setQuantidadeStr(String(atual + step));
  };

  return (
    <Dialog open={!!produto} onOpenChange={onOpenChange}>
      <DialogContent
        data-mia-modal="ajustar-expositora"
        className="sm:max-w-[425px] bg-white/95 dark:bg-zinc-900/95 backdrop-blur-xl border-white/20 dark:border-white/10 rounded-3xl shadow-2xl"
      >
        <DialogHeader>
          <DialogTitle className="text-xl font-serif font-bold text-[#2D362E] dark:text-[#E6DCCF] break-words pr-6">
            Ajustar expositora
          </DialogTitle>
          <DialogDescription>
            Corrige só o saldo da vitrine — a câmara fria não muda.
          </DialogDescription>
        </DialogHeader>

        {produto && (
          <div className="space-y-5 py-2">
            <div className="rounded-2xl bg-[#57715B]/5 border border-[#57715B]/10 p-4">
              <div className="font-bold text-[#2D362E] dark:text-[#E6DCCF] break-words">
                {produto.nome}
              </div>
              <div className="text-xs text-muted-foreground mt-1 tabular-nums">
                Saldo atual da expositora:{' '}
                <span className={cn('font-bold', saldoAtual < 0 && 'text-red-600')}>
                  {saldoAtual}
                </span>
              </div>
            </div>

            <Tabs value={modo} onValueChange={handleModoChange}>
              <TabsList className="grid w-full grid-cols-2 rounded-xl">
                <TabsTrigger value="delta" data-mia-action="modo-delta" className="rounded-lg">
                  Ajuste (+/−)
                </TabsTrigger>
                <TabsTrigger
                  value="absoluto"
                  data-mia-action="modo-recontagem"
                  className="rounded-lg"
                >
                  Recontagem
                </TabsTrigger>
              </TabsList>
            </Tabs>

            <div className="space-y-2">
              <Label htmlFor="ajuste-quantidade">
                {modo === 'delta' ? 'Quanto somar ou tirar' : 'Novo saldo contado'}
              </Label>
              <div className="flex gap-2">
                {modo === 'delta' && (
                  <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    data-mia-action="delta-menos"
                    onClick={() => stepDelta(-1)}
                    className="h-11 w-11 shrink-0 rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10"
                  >
                    <Minus className="w-4 h-4" />
                  </Button>
                )}
                <Input
                  id="ajuste-quantidade"
                  data-mia-field="quantidade"
                  type="number"
                  inputMode="numeric"
                  step={1}
                  min={modo === 'absoluto' ? 0 : undefined}
                  value={quantidadeStr}
                  onChange={(e) => setQuantidadeStr(e.target.value)}
                  placeholder={modo === 'delta' ? 'Ex.: -2 ou 3' : String(Math.max(saldoAtual, 0))}
                  className="h-11 rounded-xl text-lg font-bold tabular-nums text-center"
                />
                {modo === 'delta' && (
                  <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    data-mia-action="delta-mais"
                    onClick={() => stepDelta(1)}
                    className="h-11 w-11 shrink-0 rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10"
                  >
                    <Plus className="w-4 h-4" />
                  </Button>
                )}
              </div>
              {!quantidadeInvalida && (
                <p className="text-xs text-muted-foreground tabular-nums">
                  Saldo: {saldoAtual} →{' '}
                  <span
                    className={cn(
                      'font-bold',
                      saldoNovo < 0 ? 'text-red-600' : 'text-[#57715B] dark:text-[#8FAE94]',
                    )}
                  >
                    {saldoNovo}
                  </span>
                </p>
              )}
            </div>

            <div className="space-y-2">
              <Label>Motivo</Label>
              <Select value={motivo} onValueChange={(v) => setMotivo(v as AjusteMotivo)}>
                <SelectTrigger
                  className="h-11 rounded-xl"
                  data-mia-filter="motivo"
                  data-mia-options={AJUSTE_MOTIVO_OPTIONS.map((m) => m.value).join(',')}
                >
                  <SelectValue placeholder="Selecione o motivo" />
                </SelectTrigger>
                <SelectContent>
                  {AJUSTE_MOTIVO_OPTIONS.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="ajuste-observacoes">Observações (opcional)</Label>
              <Textarea
                id="ajuste-observacoes"
                data-mia-field="observacoes"
                value={observacoes}
                onChange={(e) => setObservacoes(e.target.value)}
                placeholder="Ex.: caiu no chão na reposição"
                className="rounded-xl resize-none"
                rows={2}
              />
            </div>
          </div>
        )}

        <DialogFooter className="gap-2 sm:gap-0">
          <Button
            variant="ghost"
            onClick={() => onOpenChange(false)}
            disabled={isPending}
            className="rounded-xl h-11"
          >
            Cancelar
          </Button>
          <Button
            data-mia-action="confirmar-ajuste"
            onClick={() =>
              motivo &&
              onConfirm({
                quantidade,
                modo,
                motivo,
                observacoes: observacoes.trim() || undefined,
              })
            }
            disabled={quantidadeInvalida || !motivo || isPending}
            className="rounded-xl h-11 bg-[#57715B] hover:bg-[#465b49] text-white font-bold"
          >
            <SlidersHorizontal className="w-4 h-4 mr-2" />
            {isPending ? 'Ajustando...' : 'Confirmar ajuste'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * @module features/pronta-entrega/ui/ContagemExpositoraSheet
 *
 * Fluxo guiado de contagem da expositora: lista todos os produtos da lista
 * unificada com input numérico por produto. Ao confirmar, aplica
 * `ajustar_expositora` em modo 'absoluto' SÓ nos produtos preenchidos.
 * Campos vazios não são alterados.
 */

import { useEffect, useMemo, useState } from 'react';
import { ClipboardList } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from '@/shared/ui/sheet';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { cn } from '@/shared/lib/utils';
import type { SaldoRow } from '../model/saldos';

export interface ContagemEntry {
  produtoId: number;
  quantidade: number;
}

interface ContagemExpositoraSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  rows: SaldoRow[];
  onConfirm: (entries: ContagemEntry[]) => void;
  isPending: boolean;
}

/**
 * Sheet de contagem guiada da expositora (recontagem/contagem inicial).
 */
export function ContagemExpositoraSheet({
  open,
  onOpenChange,
  rows,
  onConfirm,
  isPending,
}: ContagemExpositoraSheetProps) {
  const [values, setValues] = useState<Record<number, string>>({});

  useEffect(() => {
    if (open) setValues({});
  }, [open]);

  const entries = useMemo<ContagemEntry[]>(() => {
    return rows
      .map((row) => {
        const raw = (values[row.produtoId] ?? '').trim();
        if (raw === '') return null;
        const n = Number(raw);
        if (!Number.isInteger(n) || n < 0) return null;
        return { produtoId: row.produtoId, quantidade: n };
      })
      .filter((e): e is ContagemEntry => e !== null);
  }, [rows, values]);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        data-mia-modal="contagem-expositora"
        className="w-full sm:max-w-md flex flex-col p-0"
      >
        <SheetHeader className="px-5 pt-5 text-left">
          <SheetTitle className="font-serif text-[#2D362E] dark:text-[#E6DCCF] flex items-center gap-2">
            <ClipboardList className="w-5 h-5 text-[#57715B]" /> Contagem da expositora
          </SheetTitle>
          <SheetDescription>
            Conte o que está na vitrine e preencha. Campos vazios não são alterados.
          </SheetDescription>
        </SheetHeader>

        <ScrollArea className="flex-1 px-5 mt-2">
          <div className="space-y-2 pb-4">
            {rows.length === 0 && (
              <p className="text-sm text-muted-foreground py-8 text-center">
                Nenhum produto com saldo nesta loja.
              </p>
            )}
            {rows.map((row) => (
              <div
                key={row.produtoId}
                className="flex items-center gap-3 rounded-2xl border border-[#57715B]/10 bg-white/60 dark:bg-white/5 p-3"
              >
                <div className="flex-1 min-w-0">
                  <div className="font-bold text-sm leading-snug text-[#2D362E] dark:text-[#E6DCCF] break-words">
                    {row.nome}
                  </div>
                  <div
                    className={cn(
                      'text-[11px] tabular-nums',
                      row.expositora < 0 ? 'text-red-600 font-bold' : 'text-muted-foreground',
                    )}
                  >
                    Atual: {row.expositora}
                  </div>
                </div>
                <Input
                  type="number"
                  inputMode="numeric"
                  min={0}
                  step={1}
                  data-mia-field={`contagem-${row.produtoId}`}
                  aria-label={`Contagem de ${row.nome}`}
                  value={values[row.produtoId] ?? ''}
                  onChange={(e) =>
                    setValues((prev) => ({ ...prev, [row.produtoId]: e.target.value }))
                  }
                  placeholder="—"
                  className="h-11 w-20 shrink-0 rounded-xl text-center text-lg font-bold tabular-nums"
                />
              </div>
            ))}
          </div>
        </ScrollArea>

        <SheetFooter className="px-5 pb-5 pt-3 border-t border-[#57715B]/10">
          <Button
            data-mia-action="aplicar-contagem"
            onClick={() => onConfirm(entries)}
            disabled={entries.length === 0 || isPending}
            className="w-full h-12 rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white font-bold"
          >
            {isPending
              ? 'Aplicando contagem...'
              : `Aplicar contagem (${entries.length} produto${entries.length === 1 ? '' : 's'})`}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

