/**
 * @module features/pronta-entrega/ui/HistoricoExpositoraSheet
 *
 * Ledger da expositora (`expositora_movimentacoes`): badge por tipo, motivo,
 * quantidade, saldo de→para, usuário e data relativa. Últimos 200 da loja.
 */

import { ArrowRight, History } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/shared/ui/sheet';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { Skeleton } from '@/shared/ui/skeleton';
import { cn } from '@/shared/lib/utils';
import { useExpositoraHistorico } from '../model/useExpositoraHistorico';
import { motivoLabel, tipoBadge } from '../model/motivos';

interface HistoricoExpositoraSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  lojaId: number | null;
}

function formatRelative(iso: string): string {
  try {
    return formatDistanceToNow(new Date(iso), { addSuffix: true, locale: ptBR });
  } catch {
    return iso;
  }
}

/**
 * Sheet com o histórico de movimentações da expositora da loja.
 */
export function HistoricoExpositoraSheet({
  open,
  onOpenChange,
  lojaId,
}: HistoricoExpositoraSheetProps) {
  const { entries, isLoading, isError } = useExpositoraHistorico(lojaId, open);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        data-mia-modal="historico-expositora"
        className="w-full sm:max-w-md flex flex-col p-0"
      >
        <SheetHeader className="px-5 pt-5 text-left">
          <SheetTitle className="font-serif text-[#2D362E] dark:text-[#E6DCCF] flex items-center gap-2">
            <History className="w-5 h-5 text-[#57715B]" /> Histórico da expositora
          </SheetTitle>
          <SheetDescription>Últimas 200 movimentações da vitrine desta loja.</SheetDescription>
        </SheetHeader>

        <ScrollArea className="flex-1 px-5 mt-2">
          <div className="space-y-2 pb-6">
            {isLoading &&
              [1, 2, 3, 4, 5].map((i) => <Skeleton key={i} className="h-20 rounded-2xl" />)}

            {isError && (
              <p className="text-sm text-red-600 py-8 text-center">
                Erro ao carregar o histórico. Feche e abra de novo pra tentar novamente.
              </p>
            )}

            {!isLoading && !isError && entries.length === 0 && (
              <p className="text-sm text-muted-foreground py-8 text-center">
                Nenhuma movimentação registrada ainda.
              </p>
            )}

            {entries.map((entry) => {
              const badge = tipoBadge(entry.tipo);
              return (
                <div
                  key={entry.id}
                  className="rounded-2xl border border-[#57715B]/10 bg-white/60 dark:bg-white/5 p-3"
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <span
                        className={cn(
                          'inline-block rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider',
                          badge.className,
                        )}
                      >
                        {badge.label}
                      </span>
                      <div className="font-bold text-sm leading-snug text-[#2D362E] dark:text-[#E6DCCF] break-words mt-1">
                        {entry.produtoNome}
                      </div>
                    </div>
                    <span className="text-[10px] text-muted-foreground whitespace-nowrap shrink-0 mt-0.5">
                      {formatRelative(entry.createdAt)}
                    </span>
                  </div>

                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-2 text-xs text-muted-foreground tabular-nums">
                    <span>
                      Motivo: <span className="font-medium">{motivoLabel(entry.motivo)}</span>
                    </span>
                    <span>
                      Qtd: <span className="font-medium">{entry.quantidade}</span>
                    </span>
                    <span className="inline-flex items-center gap-1">
                      Saldo: {entry.saldoAnterior}
                      <ArrowRight className="w-3 h-3" />
                      <span
                        className={cn(
                          'font-bold',
                          entry.saldoNovo < 0
                            ? 'text-red-600'
                            : 'text-[#57715B] dark:text-[#8FAE94]',
                        )}
                      >
                        {entry.saldoNovo}
                      </span>
                    </span>
                  </div>

                  {entry.observacoes && (
                    <p className="text-[11px] italic text-muted-foreground mt-1 break-words">
                      {entry.observacoes}
                    </p>
                  )}
                  {entry.usuarioNome && (
                    <p className="text-[10px] text-muted-foreground/70 mt-1 truncate">
                      Por: {entry.usuarioNome}
                    </p>
                  )}
                </div>
              );
            })}
          </div>
        </ScrollArea>
      </SheetContent>
    </Sheet>
  );
}

/**
 * @module features/pronta-entrega/ui/ProntaEntrega.page
 *
 * Pronta Entrega v2 — saldo unificado da loja: câmara fria (`estoque`) ×
 * expositora/vitrine (`expositora_estoque`), com movimentação atômica pra
 * vitrine, ajustes com motivo, contagem guiada e histórico (ledger).
 * Fábrica (loja_id=1) não tem expositora — mostra empty state.
 */

import { useCallback, useMemo, useRef, useState } from 'react';
import {
  AlertTriangle,
  ClipboardList,
  Factory,
  History,
  Monitor,
  PackageOpen,
  RotateCw,
  Search,
  Snowflake,
  Store,
} from 'lucide-react';
import { toast } from 'sonner';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { Skeleton } from '@/shared/ui/skeleton';
import { GlassCard } from '@/shared/ui/glass-card';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { PermissionBlur } from '@/shared/ui/PermissionBlur';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { useStore } from '@/shared/contexts/StoreContext';
import { cn } from '@/shared/lib/utils';
import { useMiaPageContext } from '@/features/mia/hooks/useMiaPageContext';
import { useMiaProntaEntregaActions } from '@/features/mia/model/hooks';
import {
  FABRICA_LOJA_ID,
  filterSaldos,
  normalizeSearchText,
  type SaldoRow,
} from '../model/saldos';
import { useProntaEntregaSaldos } from '../model/useProntaEntregaSaldos';
import { useExpositoraMutations } from '../model/useExpositoraMutations';
import { SaldosList } from './SaldosList';
import { MoverParaExpositoraModal } from './MoverParaExpositoraModal';
import { AjusteExpositoraModal, type AjusteSubmit } from './AjusteExpositoraModal';
import { ContagemExpositoraSheet, type ContagemEntry } from './ContagemExpositoraSheet';
import { HistoricoExpositoraSheet } from './HistoricoExpositoraSheet';

export default function ProntaEntregaPage() {
  useMiaPageContext({
    description:
      'Pronta Entrega — saldo da câmara fria (estoque) e da expositora/vitrine por loja. Permite expor produto na vitrine, ajustar saldo com motivo, fazer contagem guiada e ver o histórico (ledger).',
    natural_language_hints:
      '"expor X" / "colocar X na vitrine" = botão Expor (mover_para_expositora); "ajustar X" / "perda/vencido/degustação" = botão Ajustar (ajustar_expositora); "recontagem" / "contagem" = botão Contagem; "histórico da vitrine" = botão Histórico; saldo negativo na expositora = furo de processo, recomendar recontagem.',
    capabilities: [
      'consultar_saldos',
      'expor_na_vitrine',
      'ajustar_expositora',
      'contagem_guiada',
      'historico',
    ],
    destructive_actions: ['ajustar_expositora', 'aplicar_contagem'],
    primary_entity: 'expositora_estoque',
  });

  const { canViewProntaEntrega, isAdmin } = usePermissions();
  const { selectedStore, stores } = useStore();

  // Admin pode olhar outra loja sem trocar a loja global; usuário comum usa a própria
  const [storeOverride, setStoreOverride] = useState<number | null>(null);
  const lojaId = (isAdmin() ? storeOverride : null) ?? selectedStore?.id ?? null;
  const isFabrica = lojaId === FABRICA_LOJA_ID;

  const [search, setSearch] = useState('');
  const [exporProduto, setExporProduto] = useState<SaldoRow | null>(null);
  const [ajusteProduto, setAjusteProduto] = useState<SaldoRow | null>(null);
  const [contagemOpen, setContagemOpen] = useState(false);
  const [historicoOpen, setHistoricoOpen] = useState(false);
  const [contagemPending, setContagemPending] = useState(false);

  const { rows, isLoading, isError, refetch } = useProntaEntregaSaldos(lojaId);
  const { mover, ajustar } = useExpositoraMutations(lojaId);

  const filtered = useMemo(() => filterSaldos(rows, search), [rows, search]);

  const kpis = useMemo(() => {
    let totalEstoque = 0;
    let totalExpositora = 0;
    let negativos = 0;
    for (const row of rows) {
      totalEstoque += row.estoque;
      totalExpositora += row.expositora;
      if (row.expositora < 0) negativos += 1;
    }
    return { totalEstoque, totalExpositora, negativos };
  }, [rows]);

  // ── MIA: callbacks estáveis (handlers são registrados uma única vez) ──
  const rowsRef = useRef<SaldoRow[]>(rows);
  rowsRef.current = rows;

  const miaRefetch = useCallback(() => {
    void refetch();
  }, [refetch]);

  const miaOpenExporModal = useCallback((productName?: string) => {
    if (!productName) {
      const first = rowsRef.current[0] ?? null;
      if (first) setExporProduto(first);
      else toast.error('Nenhum produto com saldo pra expor nesta loja.');
      return;
    }
    const term = normalizeSearchText(productName);
    const match = rowsRef.current.find((r) => normalizeSearchText(r.nome).includes(term));
    if (match) setExporProduto(match);
    else toast.error(`Produto "${productName}" não encontrado na lista da loja.`);
  }, []);

  useMiaProntaEntregaActions({
    setSearch,
    refetch: miaRefetch,
    openExporModal: miaOpenExporModal,
  });

  // ── Handlers das mutations (erros já viram toast no hook) ──
  const handleExporConfirm = async (quantidade: number, observacoes?: string) => {
    if (!exporProduto) return;
    try {
      await mover.mutateAsync({ produtoId: exporProduto.produtoId, quantidade, observacoes });
      toast.success(`${quantidade}× ${exporProduto.nome} movido pra expositora.`);
      setExporProduto(null);
    } catch {
      // erro já exibido via toast no hook de mutation
    }
  };

  const handleAjusteConfirm = async (input: AjusteSubmit) => {
    if (!ajusteProduto) return;
    try {
      const result = await ajustar.mutateAsync({
        produtoId: ajusteProduto.produtoId,
        ...input,
      });
      toast.success(
        `Expositora de ${ajusteProduto.nome} ajustada: ${result.saldo_anterior ?? '?'} → ${result.saldo ?? '?'}.`,
      );
      setAjusteProduto(null);
    } catch {
      // erro já exibido via toast no hook de mutation
    }
  };

  const handleContagemConfirm = async (entries: ContagemEntry[]) => {
    // Loja inteira zerada na expositora = primeira contagem
    const motivo = rows.every((r) => r.expositora === 0) ? 'contagem_inicial' : 'recontagem';
    setContagemPending(true);
    let aplicados = 0;
    let falhas = 0;
    for (const entry of entries) {
      try {
        await ajustar.mutateAsync({
          produtoId: entry.produtoId,
          quantidade: entry.quantidade,
          modo: 'absoluto',
          motivo,
        });
        aplicados += 1;
      } catch {
        falhas += 1;
      }
    }
    setContagemPending(false);
    if (aplicados > 0) {
      toast.success(`Contagem aplicada em ${aplicados} produto${aplicados === 1 ? '' : 's'}.`);
    }
    if (falhas > 0) {
      toast.error(`${falhas} produto${falhas === 1 ? '' : 's'} falharam na contagem.`);
    } else {
      setContagemOpen(false);
    }
  };

  const acoesDisponiveis = lojaId !== null && !isFabrica;

  return (
    <PermissionBlur hasPermission={canViewProntaEntrega()} moduleName="Pronta Entrega">
      <MommaPageLayout>
        <div
          data-mia-page="pronta-entrega"
          data-mia-domain="estoque"
          className="flex-1 w-full max-w-[1400px] mx-auto px-4 md:px-8 pt-8 md:pt-10 pb-10 space-y-5 md:space-y-6"
        >
          {/* Header */}
          <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2.5 rounded-2xl bg-[#57715B]/10 shrink-0">
                <Monitor className="w-6 h-6 text-[#57715B]" />
              </div>
              <div>
                <h1 className="text-2xl md:text-4xl font-bold tracking-tight font-serif text-[#2D362E] dark:text-[#E6DCCF] leading-none">
                  Pronta Entrega
                </h1>
                <p className="text-[10px] md:text-xs uppercase tracking-widest text-[#57715B] dark:text-[#8FAE94] font-bold opacity-80 mt-1.5">
                  Câmara fria × expositora da loja
                </p>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-2">
              {isAdmin() && (
                <Select
                  value={lojaId !== null ? String(lojaId) : undefined}
                  onValueChange={(v) => setStoreOverride(Number(v))}
                >
                  <SelectTrigger
                    className="h-10 w-[170px] rounded-xl border border-[#57715B]/20 bg-white/60 dark:bg-zinc-800/40 backdrop-blur-sm text-xs font-medium"
                    data-mia-filter="loja"
                    data-mia-options={stores.map((s) => s.name).join(',')}
                  >
                    <Store className="w-3.5 h-3.5 mr-1.5 text-[#57715B] shrink-0" />
                    <SelectValue placeholder="Loja" />
                  </SelectTrigger>
                  <SelectContent>
                    {stores.map((store) => (
                      <SelectItem key={store.id} value={String(store.id)}>
                        {store.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
              <Button
                variant="outline"
                data-mia-action="abrir-contagem"
                data-mia-expects-modal-open="contagem-expositora"
                onClick={() => setContagemOpen(true)}
                disabled={!acoesDisponiveis}
                className="h-10 rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 font-bold bg-white/60 dark:bg-zinc-800/40 backdrop-blur-sm"
              >
                <ClipboardList className="w-4 h-4 sm:mr-1.5" />
                <span className="hidden sm:inline">Contagem</span>
              </Button>
              <Button
                variant="outline"
                data-mia-action="abrir-historico"
                data-mia-expects-modal-open="historico-expositora"
                onClick={() => setHistoricoOpen(true)}
                disabled={!acoesDisponiveis}
                className="h-10 rounded-xl border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 font-bold bg-white/60 dark:bg-zinc-800/40 backdrop-blur-sm"
              >
                <History className="w-4 h-4 sm:mr-1.5" />
                <span className="hidden sm:inline">Histórico</span>
              </Button>
            </div>
          </div>

          {isFabrica ? (
            // Empty state: Fábrica não tem expositora
            <GlassCard className="p-8 md:p-12 text-center" variant="premium">
              <Factory className="w-12 h-12 mx-auto text-[#57715B]/40 mb-4" />
              <h2 className="text-lg md:text-xl font-serif font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                A Fábrica não tem expositora
              </h2>
              <p className="text-sm text-muted-foreground mt-2 max-w-md mx-auto">
                A expositora é a vitrine/balcão de cada loja. Selecione uma loja pra ver e
                movimentar os saldos de pronta entrega.
              </p>
            </GlassCard>
          ) : (
            <>
              {/* KPIs compactos */}
              <div className="grid grid-cols-3 gap-2 md:gap-4">
                <div className="relative overflow-hidden group rounded-2xl md:rounded-[2rem] border border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-md shadow-sm hover:shadow-md p-3 md:p-5">
                  <Snowflake className="absolute top-1 right-1 w-10 h-10 md:w-16 md:h-16 text-[#57715B] opacity-10 group-hover:opacity-20 transition-opacity" />
                  <div className="text-[9px] md:text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Na câmara
                  </div>
                  <div className="text-xl md:text-2xl font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                    {isLoading ? '—' : kpis.totalEstoque}
                  </div>
                </div>
                <div className="relative overflow-hidden group rounded-2xl md:rounded-[2rem] border border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60 backdrop-blur-md shadow-sm hover:shadow-md p-3 md:p-5">
                  <Monitor className="absolute top-1 right-1 w-10 h-10 md:w-16 md:h-16 text-[#57715B] opacity-10 group-hover:opacity-20 transition-opacity" />
                  <div className="text-[9px] md:text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Na expositora
                  </div>
                  <div className="text-xl md:text-2xl font-bold tabular-nums text-[#57715B] dark:text-[#8FAE94]">
                    {isLoading ? '—' : kpis.totalExpositora}
                  </div>
                </div>
                <div
                  className={cn(
                    'relative overflow-hidden group rounded-2xl md:rounded-[2rem] border backdrop-blur-md shadow-sm hover:shadow-md p-3 md:p-5',
                    kpis.negativos > 0
                      ? 'border-red-200 dark:border-red-900/40 bg-red-50/60 dark:bg-red-900/10'
                      : 'border-[#57715B]/10 bg-white/60 dark:bg-[#1A1A1A]/60',
                  )}
                >
                  <AlertTriangle
                    className={cn(
                      'absolute top-1 right-1 w-10 h-10 md:w-16 md:h-16 opacity-10 group-hover:opacity-20 transition-opacity',
                      kpis.negativos > 0 ? 'text-red-600' : 'text-[#57715B]',
                    )}
                  />
                  <div className="text-[9px] md:text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Negativos
                  </div>
                  <div
                    className={cn(
                      'text-xl md:text-2xl font-bold tabular-nums',
                      kpis.negativos > 0
                        ? 'text-red-600 dark:text-red-400'
                        : 'text-[#2D362E] dark:text-[#E6DCCF]',
                    )}
                  >
                    {isLoading ? '—' : kpis.negativos}
                  </div>
                </div>
              </div>

              {/* Busca */}
              <div className="relative w-full md:max-w-sm">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  data-mia-field="busca-produto"
                  placeholder="Buscar produto..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-9 h-11 rounded-xl bg-white/60 dark:bg-zinc-800/40 border-[#57715B]/10 backdrop-blur-sm"
                />
              </div>

              {/* Lista / estados */}
              {isLoading ? (
                <div className="space-y-2">
                  {[1, 2, 3, 4, 5].map((i) => (
                    <Skeleton key={i} className="h-[88px] md:h-14 rounded-2xl" />
                  ))}
                </div>
              ) : isError ? (
                <GlassCard className="p-8 text-center" gradient={false}>
                  <AlertTriangle className="w-10 h-10 mx-auto text-red-500/60 mb-3" />
                  <p className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                    Erro ao carregar os saldos
                  </p>
                  <p className="text-sm text-muted-foreground mt-1">
                    Verifique a conexão e tente de novo.
                  </p>
                  <Button
                    data-mia-action="tentar-novamente"
                    onClick={() => void refetch()}
                    className="mt-4 h-10 rounded-xl bg-[#57715B] hover:bg-[#465b49] text-white font-bold"
                  >
                    <RotateCw className="w-4 h-4 mr-2" /> Tentar novamente
                  </Button>
                </GlassCard>
              ) : rows.length === 0 ? (
                <GlassCard className="p-8 md:p-12 text-center" gradient={false}>
                  <PackageOpen className="w-12 h-12 mx-auto text-[#57715B]/30 mb-4" />
                  <p className="font-serif font-bold text-lg text-[#2D362E] dark:text-[#E6DCCF]">
                    Nenhum produto com saldo
                  </p>
                  <p className="text-sm text-muted-foreground mt-2 max-w-md mx-auto">
                    Quando a loja receber produtos na câmara fria ou registrar itens na
                    expositora, eles aparecem aqui.
                  </p>
                </GlassCard>
              ) : filtered.length === 0 ? (
                <GlassCard className="p-8 text-center" gradient={false}>
                  <Search className="w-10 h-10 mx-auto text-[#57715B]/30 mb-3" />
                  <p className="text-sm text-muted-foreground">
                    Nenhum produto encontrado pra busca "{search}".
                  </p>
                </GlassCard>
              ) : (
                <SaldosList rows={filtered} onExpor={setExporProduto} onAjustar={setAjusteProduto} />
              )}
            </>
          )}
        </div>

        {/* Modais e sheets */}
        <MoverParaExpositoraModal
          produto={exporProduto}
          onOpenChange={(open) => !open && setExporProduto(null)}
          onConfirm={handleExporConfirm}
          isPending={mover.isPending}
        />
        <AjusteExpositoraModal
          produto={ajusteProduto}
          onOpenChange={(open) => !open && setAjusteProduto(null)}
          onConfirm={handleAjusteConfirm}
          isPending={ajustar.isPending}
        />
        <ContagemExpositoraSheet
          open={contagemOpen}
          onOpenChange={setContagemOpen}
          rows={rows}
          onConfirm={handleContagemConfirm}
          isPending={contagemPending}
        />
        <HistoricoExpositoraSheet
          open={historicoOpen}
          onOpenChange={setHistoricoOpen}
          lojaId={lojaId}
        />
      </MommaPageLayout>
    </PermissionBlur>
  );
}

// MIA actions da Pronta Entrega v2 (câmara fria × expositora).
//
// Modelo novo: a página não tem mais kanban congelado/resfriado/expositor —
// os saldos vêm de `estoque` + `expositora_estoque` e as mutações passam
// pelos RPCs `mover_para_expositora` / `ajustar_expositora`.
//
// Handlers mantidos: pronta_search, pronta_refresh, clear_filters e
// pronta_create (semântica nova: abrir o modal "Expor na vitrine").
// Handlers de kanban (pronta_move, pronta_switch_view, pronta_consume,
// pronta_delete, pronta_open_detail, pronta_analytics_filter) foram
// removidos — backend MIA será atualizado na fase 2.

import { useMemo } from 'react';
import { useMiaActions } from '@/hooks/useMiaActions';
import type { MiaActionHandler } from '@/types/mia';

export interface ProntaEntregaMiaInterface {
  /** Preenche a busca por nome de produto. */
  setSearch: (value: string) => void;
  /** Refaz a query dos saldos (estoque + expositora). */
  refetch: () => void;
  /**
   * Abre o modal "Expor na vitrine" (mover_para_expositora). Com
   * `productName`, pré-seleciona o produto correspondente da lista.
   */
  openExporModal: (productName?: string) => void;
}

/**
 * Registra os handlers MIA da rota /pronta-entrega.
 *
 * IMPORTANTE: `useMiaActions` registra os handlers UMA vez (não re-registra
 * em re-render) — os callbacks da interface devem ser estáveis (setState,
 * refetch do React Query, ou useCallback com refs).
 */
export function useMiaProntaEntregaActions(iface: ProntaEntregaMiaInterface): void {
  const { setSearch, refetch, openExporModal } = iface;

  const handlers = useMemo<Record<string, MiaActionHandler>>(
    () => ({
      // ── Buscar produto ──
      pronta_search: {
        id: 'pronta_search',
        description: 'Buscar produto na pronta entrega (filtra a lista de saldos)',
        execute: (data) => {
          if (data?.search !== undefined) {
            setSearch(String(data.search));
          }
        },
      },

      // ── Adicionar na vitrine (semântica nova do pronta_create) ──
      pronta_create: {
        id: 'pronta_create',
        description:
          'Abrir o modal de expor produto na vitrine (mover da câmara fria pra expositora)',
        execute: (data) => {
          openExporModal(
            data?.product_name !== undefined ? String(data.product_name) : undefined,
          );
        },
      },

      // ── Atualizar dados ──
      pronta_refresh: {
        id: 'pronta_refresh',
        description: 'Atualizar os saldos da pronta entrega (câmara fria e expositora)',
        execute: () => {
          refetch();
        },
      },

      // ── Limpar filtros ──
      clear_filters: {
        id: 'clear_filters',
        description: 'Limpar a busca da pronta entrega',
        execute: () => {
          setSearch('');
        },
      },
    }),
    [setSearch, refetch, openExporModal],
  );

  useMiaActions('/pronta-entrega', handlers);
}

