import { describe, it, expect } from 'vitest';
import {
  mergeSaldos,
  filterSaldos,
  normalizeSearchText,
  type SaldoSourceRow,
} from './saldos';

const src = (
  produtoId: number,
  nome: string,
  quantidade: number,
  setor: string | null = 'Doces',
): SaldoSourceRow => ({ produtoId, nome, setor, quantidade });

describe('mergeSaldos', () => {
  it('inclui produto que só tem estoque (câmara)', () => {
    const result = mergeSaldos([src(1, 'Naked P pistache', 8)], []);
    expect(result).toHaveLength(1);
    expect(result[0]).toMatchObject({
      produtoId: 1,
      nome: 'Naked P pistache',
      estoque: 8,
      expositora: 0,
      total: 8,
    });
  });

  it('inclui produto que só tem expositora', () => {
    const result = mergeSaldos([], [src(2, 'Vulcão churros', 4)]);
    expect(result).toHaveLength(1);
    expect(result[0]).toMatchObject({
      produtoId: 2,
      estoque: 0,
      expositora: 4,
      total: 4,
    });
  });

  it('soma estoque e expositora no total quando o produto está em ambos', () => {
    const result = mergeSaldos(
      [src(3, 'Dressed M chocolate', 10)],
      [src(3, 'Dressed M chocolate', 2)],
    );
    expect(result).toHaveLength(1);
    expect(result[0]).toMatchObject({ estoque: 10, expositora: 2, total: 12 });
  });

  it('mantém produto com expositora negativa mesmo sem estoque', () => {
    const result = mergeSaldos([], [src(4, 'Cuba gelato', -3)]);
    expect(result).toHaveLength(1);
    expect(result[0]).toMatchObject({ estoque: 0, expositora: -3, total: -3 });
  });

  it('expositora negativa com estoque positivo abate o total', () => {
    const result = mergeSaldos([src(5, 'Vulcão limão', 6)], [src(5, 'Vulcão limão', -2)]);
    expect(result[0]).toMatchObject({ estoque: 6, expositora: -2, total: 4 });
  });

  it('exclui produto com estoque 0 e expositora 0', () => {
    const result = mergeSaldos([src(6, 'Sem saldo', 0)], [src(7, 'Zerado na vitrine', 0)]);
    expect(result).toHaveLength(0);
  });

  it('ordena por nome (pt-BR)', () => {
    const result = mergeSaldos(
      [src(1, 'Vulcão churros', 1), src(2, 'Água de coco', 1), src(3, 'Naked P pistache', 1)],
      [],
    );
    expect(result.map((r) => r.nome)).toEqual([
      'Água de coco',
      'Naked P pistache',
      'Vulcão churros',
    ]);
  });

  it('soma linhas duplicadas do mesmo produto', () => {
    const result = mergeSaldos(
      [src(8, 'Duplicado', 3), src(8, 'Duplicado', 2)],
      [src(8, 'Duplicado', 1), src(8, 'Duplicado', 1)],
    );
    expect(result).toHaveLength(1);
    expect(result[0]).toMatchObject({ estoque: 5, expositora: 2, total: 7 });
  });

  it('usa nome/setor da expositora quando faltam no estoque', () => {
    const result = mergeSaldos(
      [src(9, '', 2, null)],
      [src(9, 'Naked G chocolate', 1, 'Doces')],
    );
    expect(result[0].nome).toBe('Naked G chocolate');
    expect(result[0].setor).toBe('Doces');
  });
});

describe('filterSaldos', () => {
  const rows = mergeSaldos(
    [src(1, 'Vulcão churros', 5), src(2, 'Naked P pistache', 3), src(3, 'Vulcão limão', 2)],
    [],
  );

  it('retorna tudo com busca vazia ou só espaços', () => {
    expect(filterSaldos(rows, '')).toHaveLength(3);
    expect(filterSaldos(rows, '   ')).toHaveLength(3);
  });

  it('filtra por nome case-insensitive', () => {
    const result = filterSaldos(rows, 'NAKED');
    expect(result).toHaveLength(1);
    expect(result[0].nome).toBe('Naked P pistache');
  });

  it('ignora acentos na busca ("vulcao" encontra "Vulcão")', () => {
    expect(filterSaldos(rows, 'vulcao')).toHaveLength(2);
    expect(filterSaldos(rows, 'limao')).toHaveLength(1);
  });

  it('retorna vazio quando nada combina', () => {
    expect(filterSaldos(rows, 'brigadeiro')).toHaveLength(0);
  });
});

describe('normalizeSearchText', () => {
  it('remove acentos e baixa a caixa', () => {
    expect(normalizeSearchText('Vulcão LIMÃO')).toBe('vulcao limao');
    expect(normalizeSearchText('Degustação')).toBe('degustacao');
  });
});

import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';
import { TooltipProvider } from '@/shared/ui/tooltip';
import { SaldosList } from './SaldosList';
import { filterSaldos, type SaldoRow } from '../model/saldos';

const rows: SaldoRow[] = [
  {
    produtoId: 1,
    nome: 'Naked P pistache',
    setor: 'Doces & Sobremesas',
    estoque: 8,
    expositora: 3,
    total: 11,
  },
  {
    produtoId: 2,
    nome: 'Vulcão churros',
    setor: 'Doces & Sobremesas',
    estoque: 0,
    expositora: -2,
    total: -2,
  },
];

function renderList(data: SaldoRow[] = rows) {
  return render(
    <TooltipProvider>
      <SaldosList rows={data} onExpor={vi.fn()} onAjustar={vi.fn()} />
    </TooltipProvider>,
  );
}

describe('SaldosList', () => {
  it('renderiza os 3 saldos (estoque, expositora, total) de cada produto', () => {
    renderList();

    // Nome aparece (tabela desktop + card mobile coexistem no DOM)
    expect(screen.getAllByText('Naked P pistache').length).toBeGreaterThan(0);

    // Expositora via testid (desktop + mobile)
    const expositora = screen.getAllByTestId('expositora-1');
    expect(expositora.length).toBeGreaterThan(0);
    expositora.forEach((el) => expect(el).toHaveTextContent('3'));

    // Estoque 8 e total 11 visíveis
    expect(screen.getAllByText('8').length).toBeGreaterThan(0);
    expect(screen.getAllByText('11').length).toBeGreaterThan(0);
  });

  it('destaca expositora negativa em vermelho com ícone de alerta', () => {
    renderList();

    const negativos = screen.getAllByTestId('expositora-2');
    expect(negativos.length).toBeGreaterThan(0);
    for (const el of negativos) {
      expect(el.className).toContain('text-red-600');
      expect(el).toHaveTextContent('-2');
      // Ícone de alerta dentro do valor
      expect(el.querySelector('svg')).toBeTruthy();
    }

    // Saldo positivo NÃO fica vermelho
    const positivos = screen.getAllByTestId('expositora-1');
    for (const el of positivos) {
      expect(el.className).not.toContain('text-red-600');
    }
  });

  it('busca filtra a lista (integração com filterSaldos)', () => {
    renderList(filterSaldos(rows, 'vulcao'));

    expect(screen.queryByText('Naked P pistache')).toBeNull();
    expect(screen.getAllByText('Vulcão churros').length).toBeGreaterThan(0);
  });

  it('desabilita o botão Expor quando não há estoque na câmara', () => {
    renderList(filterSaldos(rows, 'vulcao')); // só o Vulcão (estoque 0)

    const botoesExpor = screen.getAllByRole('button', { name: /expor/i });
    expect(botoesExpor.length).toBeGreaterThan(0);
    botoesExpor.forEach((btn) => expect(btn).toBeDisabled());
  });
});
